def transform(grid):
    h, w = len(grid), len(grid[0])
    inner = Counter(v for row in grid for v in row).most_common(1)[0][0]

    def mode(values):
        return Counter(values).most_common(1)[0][0]

    # Grid-divider rows and columns have a different modal color from the
    # repeated contents of the enclosed cells.
    rlines = [r for r in range(h) if mode(grid[r]) != inner]
    clines = [c for c in range(w) if mode([grid[r][c] for r in range(h)]) != inner]
    if len(rlines) < 2 or len(clines) < 2:
        return [row[:] for row in grid]

    lattice = [[grid[r][c] for c in clines] for r in rlines]
    line_color = mode([v for row in lattice for v in row])
    hits = []
    for r in range(len(rlines) - 1):
        for c in range(len(clines) - 1):
            v = lattice[r][c]
            if v != line_color and v != inner and all(
                lattice[rr][cc] == v
                for rr, cc in ((r, c + 1), (r + 1, c), (r + 1, c + 1))
            ):
                hits.append((r, c, v))

    if not hits:
        return [[inner]]
    r0 = min(r for r, _, _ in hits)
    r1 = max(r for r, _, _ in hits)
    c0 = min(c for _, c, _ in hits)
    c1 = max(c for _, c, _ in hits)
